mapper.select:
SELECT COUNT(*)
FROM wx_customer
WHERE corp_id = #{corpId}

SELECT COUNT(*)
FROM wx_customer
WHERE corp_id = #{corpId}
  AND lost_flag = 1
  AND lost_time >= #{since}

SELECT DATE(follow_create_time) AS statDate, COUNT(*) AS cnt
FROM wx_customer
WHERE corp_id = #{corpId}
  AND follow_create_time >= #{since}
GROUP BY DATE(follow_create_time)

SELECT DATE(join_time) AS statDate, COUNT(*) AS cnt
FROM wx_group_chat_member
WHERE corp_id = #{corpId}
  AND join_time >= #{since}
GROUP BY DATE(join_time)

SELECT DATE(change_time) AS statDate, COUNT(*) AS cnt
FROM wx_group_chat_member_log
WHERE corp_id = #{corpId}
  AND change_type = 2
  AND change_time >= #{since}
GROUP BY DATE(change_time)

SELECT COUNT(*)                                             AS totalCnt,
       SUM(CASE WHEN t.status = 1 THEN 1 ELSE 0 END)        AS deliveredCnt
FROM wx_mass_target_log t
INNER JOIN wx_mass_invoke_log i ON i.id = t.invoke_id
WHERE i.corp_id = #{corpId}
  AND i.status = 'SUCCESS'
  AND i.create_time >= #{since}

      AND i.create_time < #{until}

SELECT COUNT(*)                                             AS totalCnt,
       SUM(CASE WHEN s.publish_status = 1 THEN 1 ELSE 0 END) AS publishedCnt
FROM wx_moment_send_log s
INNER JOIN wx_moment_invoke_log i ON i.id = s.invoke_id
WHERE i.corp_id = #{corpId}
  AND i.create_time >= #{since}

      AND i.create_time < #{until}
